    HasDerivAt (fun s : ℝ => fderiv ℝ f (c + s • x) x) (sndFDeriv f (c + t • x) x x) t

theorem continuousOn_hadamard_integrand {f : E → ℝ} {c x : E} {ρ : ℝ}
    (hC : ContinuousOn (sndFDeriv f) (ball c ρ)) (hx : ‖x‖ < ρ) :
