theorem bddBelow_range_comp {f : E → ℝ} {γ : ℝ → E} {K : Set E}
    (hf : Continuous f) (hK : IsCompact K) (hmem : ∀ s, γ s ∈ K) :
    BddBelow (Set.range fun s => f (γ s))

theorem eventually_eq_of_isCriticalPt [FiniteDimensional ℝ E] {f : E → ℝ} {c : E}
    (hf : ContDiff ℝ 2 f) (hnd : IsNondegenerate (sndFDeriv f c)) :
    ∀ᶠ y in 𝓝 c, IsCriticalPt f y → y = c

theorem exists_isCriticalPt_tendsto [FiniteDimensional ℝ E] {f : E → ℝ} {X : E → E}
    {γ : ℝ → E} {K : Set E}
    (hf : ContDiff ℝ 2 f) (hXc : Continuous X) (hX : IsPseudoGradient f X)
    (hnd : ∀ c, IsCriticalPt f c → IsNondegenerate (sndFDeriv f c))
    (hγ : IsIntegralCurve γ fun _ => X) (hK : IsCompact K) (hmem : ∀ s, γ s ∈ K) :
    ∃ c, IsCriticalPt f c ∧ Tendsto γ atTop (𝓝 c)

theorem BrokenPairs.intCast {Crit : Type*} [Fintype Crit] {ind : Crit → ℕ}
    {cnt : Crit → Crit → ℤ} (h : BrokenPairs ind cnt) :
    BrokenPairs ind fun a b => ((cnt a b : ℤ) : ZMod 2)

theorem chainMap_of_coneDiff_comp {d₀ : ∀ k, C (k + 1) →ₗ[R] C k}
    {d₁ : ∀ k, D (k + 1) →ₗ[R] D k} {Φ : ∀ k, C k →ₗ[R] D k}
    (h : ∀ k, (coneDiff d₀ d₁ Φ k).comp (coneDiff d₀ d₁ Φ (k + 1)) = 0) (k : ℕ)
    (x : C (k + 2)) :
    Φ (k + 1) (d₀ (k + 1) x) + d₁ (k + 1) (Φ (k + 2) x) = 0

theorem chainMap_of_coneDiff_comp_two {C D : ℕ → Type*}
    [∀ k, AddCommGroup (C k)] [∀ k, Module (ZMod 2) (C k)]
    [∀ k, AddCommGroup (D k)] [∀ k, Module (ZMod 2) (D k)]
    {d₀ : ∀ k, C (k + 1) →ₗ[ZMod 2] C k} {d₁ : ∀ k, D (k + 1) →ₗ[ZMod 2] D k}
    {Φ : ∀ k, C k →ₗ[ZMod 2] D k}
    (h : ∀ k, (coneDiff d₀ d₁ Φ k).comp (coneDiff d₀ d₁ Φ (k + 1)) = 0) (k : ℕ)
    (x : C (k + 2)) :
    Φ (k + 1) (d₀ (k + 1) x) = d₁ (k + 1) (Φ (k + 2) x)

theorem UniformSpace.Completion.hasFDerivAt_coe {𝕜 E : Type*}
    [NontriviallyNormedField 𝕜] [NormedAddCommGroup E] [NormedSpace 𝕜 E] {a : E} :
    HasFDerivAt ((↑) : E → Completion E) (toComplL : E →L[𝕜] Completion E) a

lemma dist_le_mul_volume_of_norm_lineDeriv_le {f : E → F} {a b : E} {C : ℝ}
    (hfc : ContinuousOn f (segment ℝ a b))
    (hfd : ∀ t ∈ Ioo (0 : ℝ) 1, LineDifferentiableAt ℝ f (lineMap a b t) (b - a))
    (hf' : ∀ᵐ t : ℝ, t ∈ Ioo (0 : ℝ) 1 → ‖lineDeriv ℝ f (lineMap a b t) (b - a)‖ ≤ C) :
    ‖f b - f a‖ ≤
      C * volume.real {t ∈ Ioo (0 : ℝ) 1 | lineDeriv ℝ f (lineMap a b t) (b - a) ≠ 0}

lemma dist_le_mul_volume_of_norm_fderiv_le {f : E → F} {a b : E} {C : ℝ} {s : Set E}
    (hs : IsOpen s) (hf : DiffContOnCl ℝ f s) (hab : openSegment ℝ a b ⊆ s)
    (hC : ∀ x ∈ s, ‖fderiv ℝ f x‖ ≤ C) :
    ‖f b - f a‖ ≤
      C * ‖b - a‖ * volume.real {t ∈ Ioo (0 : ℝ) 1 | fderiv ℝ f (lineMap a b t) ≠ 0}

theorem OpenPartialHomeomorph.hasFDerivAt_symm_inverse (f : OpenPartialHomeomorph E F) {y : F}
    (hy : y ∈ f.target) (hf' : (fderiv 𝕜 f (f.symm y)).IsInvertible) :
    HasFDerivAt f.symm (fderiv 𝕜 f (f.symm y)).inverse y

theorem OpenPartialHomeomorph.fderiv_symm (f : OpenPartialHomeomorph E F) {y : F}
    (hy : y ∈ f.target) (hf' : (fderiv 𝕜 f (f.symm y)).IsInvertible) :
    fderiv 𝕜 f.symm y = (fderiv 𝕜 f (f.symm y)).inverse

theorem OpenPartialHomeomorph.bijective_fderiv_symm (f : OpenPartialHomeomorph E F) {y : F}
    (hy : y ∈ f.target) (hf' : (fderiv 𝕜 f (f.symm y)).IsInvertible) :
    Bijective (fderiv 𝕜 f.symm y)

theorem OpenPartialHomeomorph.surjective_fderiv_symm (f : OpenPartialHomeomorph E F) {y : F}
    (hy : y ∈ f.target) (hf' : (fderiv 𝕜 f (f.symm y)).IsInvertible) :
    Surjective (fderiv 𝕜 f.symm y)

theorem OpenPartialHomeomorph.injective_fderiv_symm (f : OpenPartialHomeomorph E F) {y : F}
    (hy : y ∈ f.target) (hf' : (fderiv 𝕜 f (f.symm y)).IsInvertible) :
    Injective (fderiv 𝕜 f.symm y)

